import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-005.C-lrs2Ft.js";import{_ as o,o as l,c as i,a3 as n}from"./chunks/framework.DdpBa4_E.js";const z=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/70-申韩第五十六.md","filePath":"books/yan-tie-lun/70-申韩第五十六.md","lastUpdated":1794316978000}'),_={name:"books/yan-tie-lun/70-申韩第五十六.md"};function s(r,a,e,c,m,d){return l(),i("div",null,[...a[0]||(a[0]=[n('<p>申韩第五十六 【题解】</p><p>申不害、韩非是战国法家代表人物，本篇以“申韩”为题，探讨以法治国与以德治国的思想理论问题。御史认为，孔子倡导仁义，伯夷隐遁首阳山，都未能起到感化民众的作用。治国必须设明法，陈严刑，防非矫邪，像吴起、申不害、商鞅那样，依靠法令和权势来威慑民众，使他们不敢犯罪。文学则认为法令不能治本，商鞅变法破坏了秦国的良善风俗而无法恢复，而周国运用德治，不用刑罚达四十年之久。正反例证说明，治国应该从根本清除致乱之源，用道德教化取代严刑峻法。</p><p>御史曰：“待周公而为相，则世无列国[(1)]。待孔子而后学，则世无儒、墨。夫衣小缺，憏裂可以补[(2)]，而必待全匹而易之；政小缺，法令可以防，而必待《雅》、《颂》乃治之[(3)]；是犹舍邻之医，而求俞跗而后治病[(4)]，废污池之水，待江、海而后救火也。迂而不径[(5)]，阙而无务[(6)]，是以教令不从而治烦乱。夫善为政者，弊则补之，决则塞之，故吴子以法治楚、魏[(7)]，申、商以法强秦、韩也[(8)]。”</p><p>【注释】</p><p>[(1)]列国：诸多国家。</p><p>[(2)]憏（chì）：原作“襟”，据孙诒让说校改。憏，残帛。裂，缯余。</p><p>[(3)]《雅》《颂》：《诗经》中的两类诗歌，此处指代礼乐。通过弦歌讽诵来治理天下，是儒家的理想政治境界。</p><p>[(4)]俞跗（fū）：上古良医。</p><p>[(5)]迂：曲折。径：径直。</p><p>[(6)]阙：通“缺”。务：措施。</p><p>[(7)]吴子：战国前期法家先驱人物吴起。曾受魏文侯重用，担任魏国西河守，屡次破秦。后为楚悼王相，在楚国实施变法。楚悼王死后，吴起被楚国宗室大臣射杀。</p><p>[(8)]申：申不害。《史记·老子韩非列传》载：“申不害者，京人也，故郑之贱臣。学术以干韩昭侯，昭侯用为相。内修政教，外应诸侯，十五年。终韩子之身，国治兵强，无侵韩者。”商：商鞅。在秦孝公支持下实施变法，使秦国走上富强道路。《史记》中有《商君列传》。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>御史说：“如果一定要等到周公为丞相，那么世上就没有诸多国家。如果一定要等到孔子为师而后学习，那么世上就没有儒家和墨家。衣上有了小缺口，一小块布就可以把它缝补起来，而一定要等到用整匹布来换；政事上有了小缺陷，用法令就可以弥补，而一定要等到用《诗经》的《雅》、《颂》才去治理；这如同舍弃邻近医生，而一定等到求得名医俞跗之后才去治病；不用身边的污池废水，一定要等到运来长江、大海之水然后再救火。宁绕弯路而不走捷径，有了缺陷而没有补救措施，所以法令无人服从而秩序混乱。善于执政的人，有了弊政就加以弥补，有了决口就予以堵塞，因而吴起用法令治理楚国和魏国，申不害和商鞅用法术使秦国和韩国富强。”</p><p>文学曰：“有国者选众而任贤[(1)]，学者博览而就善[(2)]，何必是周公、孔子！故曰法之而已[(3)]。今商鞅反圣人之道[(4)]，变乱秦俗，其后政耗乱而不能治[(5)]，流失而不可复[(6)]，愚人纵火于沛泽[(7)]，不能复振[(8)]；蜂虿螫人[(9)]，放死不能息其毒也[(10)]。烦而止之，躁而静之，上下劳扰[(11)]，而乱益滋。故圣人教化，上与日月俱照，下与天地同流[(12)]，岂曰小补之哉！”</p><p>【注释】</p><p>[(1)]有国者：指君主。选众：从众人之中选拔人才。</p><p>[(2)]就善：择善而从。</p><p>[(3)]法：效法。</p><p>[(4)]今商鞅反圣人之道：“商鞅”之下本有“吴起”二字，据郭沫若说校删。</p><p>[(5)]耗乱：混乱。治：原作“理”，据王利器说校改。</p><p>[(6)]流失：指失去良风善俗。复：恢复。</p><p>[(7)]沛泽：沼泽地。</p><p>[(8)]复振：恢复原貌。</p><p>[(9)]虿（chài）：蝎子一类毒虫。螫（shì）：毒虫刺人，毒蛇咬人。</p><p>[(10)]放死：指将蜂、虿放跑弄死。</p><p>[(11)]劳扰：辛劳烦扰。</p><p>[(12)]同流：一起运转。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“拥有国家的君主都会从众人中选拔贤才而加以任用，学者都会博览群书择善而从，何必一定要等到周公、孔子！不过是效法他们而已。商鞅违反圣人之道，变乱秦国良善风俗，后来秦国政治变得混乱而不能治理，失去良风善俗而不可恢复。这就如同一个愚蠢的人在沼泽地放火，这片土地就再也不能恢复原貌了；蜂蝎咬了人，即使将蜂、虿放跑弄死，也不能清除它的毒液。烦扰之后加以制止，焦躁之后让其安静，上下辛劳烦扰，混乱越来越厉害。因此圣人的教化，上与日月一起光照宇宙，下与天地一同流转，怎么能说是小的弥补呢！”</p><p>御史曰：“衣缺不补，则日以甚，防漏不塞[(1)]，则日益滋[(2)]。大河之始决于瓠子也[(3)]，涓涓尔[(4)]，及其卒[(5)]，泛滥为中国害，灾梁、楚[(6)]，破曹、卫[(7)]，城郭坏沮[(8)]，蓄积漂流[(9)]，百姓木栖[(10)]，千里无庐[(11)]，令孤寡无所依，老弱无所归。故先帝闵悼其灾，亲省河堤[(12)]，举禹之功，河流以复，曹、卫以宁。百姓戴其功[(13)]，咏其德，歌‘宣房塞，万福来’焉[(14)]，亦犹是也，如何勿小补哉！”</p><p>【注释】</p><p>[(1)]防漏：堤防漏水。塞：堵塞。</p><p>[(2)]滋：指漏洞越来越大。</p><p>[(3)]大河：黄河。瓠（hù）子：地名，在今河南濮阳市南。公元前132年，黄河在瓠子决口。</p><p>[(4)]涓涓：细小的水流。尔：而已。</p><p>[(5)]卒：后来。</p><p>[(6)]梁、楚：战国时期魏、楚两国，相当于今河南黄河两岸地区和山西西南部及淮河、长江中下游地区。此处是指昔日梁、楚地区。</p><p>[(7)]曹、卫：春秋时期曹、卫两国，相当于今河南东北部与山西西南部地区。此处是指昔日曹、卫地区。</p><p>[(8)]坏沮：毁坏。</p><p>[(9)]蓄积：老百姓家中积蓄的财物。</p><p>[(10)]木栖：爬到树上栖息。</p><p>[(11)]庐：房屋。</p><p>[(12)]省：视察。《史记·孝武本纪》载：“还至瓠子，自临塞决河。留二日，沉祠而去。使二卿将卒塞决河。河徙二渠，复禹之故迹焉。”《史记·河渠书》载：“天子乃使汲仁、郭昌发卒数万人塞瓠子决。于是天子已用事万里沙，则还亲临决河，沉白马玉璧于河，令群臣从官自将军已下皆负薪填决河。”汉武帝率军民堵塞黄河缺口是在元封二年（前109）。</p><p>[(13)]戴：感谢。</p><p>[(14)]宣房塞，万福来：汉武帝创作《瓠子歌》，其中有“宣房塞兮万福来”诗句。宣房，宫名，为汉武帝塞瓠子之后所建。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>御史说：“衣服缺了不补，就会破得一天比一天厉害；堤防漏水不堵塞，漏洞就一天比一天大。黄河当初在瓠子决口，只是涓涓细流而已，到了后来，泛滥成灾，成为中国一大祸害，淹没了梁、楚地区，冲破曹、卫一带，城墙被冲垮，财物在水上漂流，老百姓爬到树上栖息，千里看不到房屋，孤儿寡妇没有依靠，老人弱者无处归依。因此已故武帝同情百姓受灾，亲自视察河堤，像当年大禹治水那样治理黄河，黄河决口因此得以修复，梁、楚、曹、卫一带终于恢复安宁。老百姓感戴武帝治河之功，歌咏他的大恩大德，歌唱‘宣房堵塞，万福来临’。其他政事也像这样，怎么不要在细小之时弥补呢！”</p><p>文学曰：“河决若瓮口[(1)]，而破千里，况礼决乎？其所害亦多矣！今断狱岁以万计，犯法兹多[(2)]，其为灾岂特曹、卫哉[(3)]！夫知塞宣房而福来，不知塞乱原而天下治也[(4)]。周国用之，刑错不用[(5)]，黎民若四时各终其序[(6)]，而天下不孤[(7)]。《颂》曰：‘绥我眉寿，介以繁祉。’[(8)]此夫为福，亦不小矣！诚信礼义如宣房，功业已立，垂拱无为[(9)]，有司何补，法令何塞也？”</p><p>【注释】</p><p>[(1)]瓮：盛物的陶器，口小，肚大。</p><p>[(2)]兹：同“滋”。</p><p>[(3)]特：仅仅，只是。</p><p>[(4)]原：同“源”。</p><p>[(5)]周国用之，刑错不用：《史记·周本纪》：“故成康之际，天下安宁，刑错四十余年不用。”错，通“措”。</p><p>[(6)]若四时各终其序：像春夏秋冬四时交替那样自然走完生命历程。</p><p>[(7)]不孤：没有孤儿。</p><p>[(8)]绥我眉寿，介以繁祉（zhǐ）：见于《诗经·周颂·雍》。绥，安抚。眉寿，长寿。介，给。繁，多。祉，福。</p><p>[(9)]垂拱：垂衣拱手，比喻无为而治。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“黄河决口最初像瓮口一样细小，最后却冲破千里河堤，何况是礼义决口呢？它的危害也够多了！如今每年断案数以万计，犯法的人越来越多，它所侵害岂止是曹、卫一带呢！你们知道堵塞宣房而幸福来临，却不知道堵塞致乱之源就会天下大治。周国这样做了，结果国家不用刑罚长达四十多年。黎民如果像春夏秋冬四时交替那样自然走完生命历程，那么天下就没有孤儿了。《诗经·周颂·雍》说：‘保佑我长寿，赐给我多福。’这样的赐福，也算不小了！朝廷如果在诚信礼义上做得像塞宣房那样，那么功业早已建立，皇帝垂衣拱手，无为而治，主管官员还有什么需要弥补，法令又有什么需要堵塞的呢？”</p><p>御史曰：“犀铫利</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>[(1)]，五谷之利而间草之害也[(2)]。明理正法，奸邪之所恶而良民之福也。故曲木恶直绳，奸邪恶正法。是以圣人审于是非，察于治乱，故设明法，陈严刑，防非矫邪，若隐括辅檠之正弧剌也[(3)]。故水者火之备，法者止奸之禁也。无法势，虽贤人不能以为治；无甲兵，虽孙、吴不能以制敌[(4)]。是以孔子倡以仁义而民从风[(5)]，伯夷遁首阳而民不可化[(6)]。”</p><p>【注释】</p><p>[(1)]犀铫（yáo）：犀利的大锄。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>：同“锄”。</p><p>[(2)]间草：苗间杂草。</p><p>[(3)]隐括：矫正曲木的工具。辅檠（qínɡ）：矫正弓的器具。弧剌：弯曲貌。</p><p>[(4)]孙、吴：春秋末年军事家孙子和战国前期军事家吴起。</p><p>[(5)]是以孔子倡以仁义而民从风：张敦仁说，“民”之下脱一“不”字。结合上下文来看，似以张说为长。从风，听从。</p><p>[(6)]伯夷遁首阳：《史记·伯夷列传》载：“武王已平殷乱，天下宗周，而伯夷、叔齐耻之，义不食周粟，隐于首阳山，采薇而食之。”遁，逃。首阳，山名，所在地说法不一。按，伯夷本为传说人物，其隐居之地难以考实。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>御史说：“犀利的大锄，锋利的锄头，对于五谷有利，而对苗间杂草有害。明确的审理，公正的法令，为奸邪之人所厌恶，而对于良民百姓来说却是福音。因此弯曲的树木厌恶取直的绳墨，奸邪之人厌恶公正的法律。所以圣人明辨是非，洞察治乱，因而设置明确的法律，发布严厉的刑法，防止为非作歹的现象，矫正奸邪之人，如同隐括、辅檠矫正曲木一样。因此，水是防备火灾的，法是禁止奸邪的。没有法律权势，即使是贤人也不能进行治理；没有坚甲利兵，即使是孙子、吴起也不能克敌制胜。所以孔子倡导仁义，而民众并不听从；伯夷逃隐到首阳山，而民众并没有被感化。”</p><p>文学曰：“法能刑人而不能使人廉，能杀人而不能使人仁。所贵良医者，贵其审消息而退邪气也[(1)]，非贵其下针石而钻肌肤也[(2)]。所贵良吏者，贵其绝恶于未萌，使之不为，非贵其拘之囹圄而刑杀之也[(3)]。今之所谓良吏者，文察则以祸其民[(4)]，强力则以厉其下[(5)]，不本法之所由生[(6)]，而专己之残心[(7)]，文诛假法[(8)]，以陷不辜[(9)]，累无罪[(10)]，以子及父，以弟及兄，一人有罪，州里惊骇，十家奔亡，若痈疽之相泞[(11)]，色淫之相连[(12)]，一节动而百枝摇。《诗》云：‘舍彼有罪，沦胥以铺。’[(13)]痛伤无罪而累也。非患铫耨之不利，患其舍草而芸苗也[(14)]。非患无准平[(15)]，患其舍枉而绳直也[(16)]。故亲近为过不必诛[(17)]，是锄不用也；疏远有功不必赏[(18)]，是苗不养也。故世不患无法，而患无必行之法也。”</p><p>【注释】</p><p>[(1)]审消息：审察脉象阴阳盛衰。</p><p>[(2)]下针石：运用银针砭石。钻：刺。</p><p>[(3)]囹圄（línɡ yǔ）：监狱。</p><p>[(4)]文察：根据法律条文苛察。</p><p>[(5)]强力：强制性运用权力。厉：残害。</p><p>[(6)]本：根据。法之所由生：立法本意。</p><p>[(7)]专己之残心：专门听凭自己残暴之心。</p><p>[(8)]文诛：深文周纳。假法：假借法令名义。</p><p>[(9)]不辜：无罪。</p><p>[(10)]累：牵连。</p><p>[(11)]痈疽（yōnɡ jū）：毒疮。泞（nìnɡ）：烂泥，此处指毒疮溃烂。</p><p>[(12)]色淫：好色淫乱。</p><p>[(13)]舍彼有罪，沦胥以铺：《诗经·小雅·雨无正》：“舍彼有罪，既伏其辜。若此无罪，沦胥以铺。”文学在此截取两句。舍，舍弃。沦，陷。胥，相。铺，遍。</p><p>[(14)]芸：锄。原作“去”，据王利器说校改。</p><p>[(15)]准平：测量水平的仪器。</p><p>[(16)]舍枉：舍弃弯曲。绳直：纠正直木。</p><p>[(17)]亲近：关系亲近的人。为过：犯错。不必诛：不坚决处罚。</p><p>[(18)]疏远：关系疏远的人。不必赏：不坚决给予奖赏。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“法律能够给人判刑，但不能使人廉洁；法律能够判人死罪，但不能使人变得仁义。人们看重良医，是看重他能够准确把握脉象的阴阳盛衰，祛除致病的邪气，而不是看重他运用银针砭石来刺激肌肤穴位。人们看重一个优秀官员，是看重他能够在罪恶尚未萌生之际斩断恶念，使人不去犯罪，而不是看重他将犯人关进大牢而将其定刑杀死。现在人们所说的优秀官员，以法律条文苛察加祸于民，以强权暴力残害下属，不根据立法的本意，而专门听凭自己的残暴之心，深文周纳，假借法令名义，来陷害无罪民众，并牵连诸多无罪亲属，儿子牵连父亲，弟弟牵连兄长，一个人有罪，一州一里都为之惊骇，十个家庭为之逃亡，如同毒疮持续溃烂，好色淫乱互相影响，一个枝节牵动，百根树枝动摇。《诗经·小雅·雨无正》说：‘舍弃那些有罪的人，相互牵连多人陷罪。’诗句伤痛的是无罪而受牵连。不怕锄草工具不锋利，怕的是舍弃杂草而锄掉禾苗。不怕没有测量水平的仪器，怕的是舍弃曲木而纠正直木。因此，关系亲近的人犯错不坚决处罚，相当于有锄头而不用；关系疏远的人有功劳不坚决给予奖赏，相当于禾苗得不到养育。因而世上不怕没有法令，怕的是没有坚决执行的法令。”</p>',103)])])}const u=o(_,[["render",s]]);export{z as __pageData,u as default};
